(function (all) { var mine = all["ru"] = all["ru"] || {}; var add = {"manual.831d0f72d242":"Начало работы","manual.f2f53974b760":"Freally Capture — настольная студия для Windows, macOS и Linux. Это руководство описывает версию 1.2.1, текущий выпуск.","manual.4b5f10daa08b":"Откройте Freally Capture. При первом запуске приложение попросит вас принять лицензионное соглашение; затем мастер настройки проверит вашу видеокарту и процессор и предложит кодировщик, размер холста и битрейт, объясняя причину каждого выбора.","manual.fe88634050bf":"Студия открывается с предпросмотром программы и доками <strong>Сцены</strong>, <strong>Источники</strong>, <strong>Микшер</strong> и <strong>Управление</strong>. Никаких учётных записей и входа в систему.","manual.4c937d2528ca":"В <strong>macOS</strong> разрешите <strong>Запись экрана</strong> — а также <strong>Камеру</strong> и <strong>Микрофон</strong>, если вы их используете, — в разделе «Системные настройки → Конфиденциальность и безопасность», затем снова откройте приложение. В <strong>Linux с Wayland</strong> собственный диалог рабочего стола спросит, какой экран или окно предоставить.","manual.adc8f305f8f8":"Добавьте первый источник (см. <a href=\"#build-a-scene\">Создание сцены</a>), и можно записывать или выходить в эфир.","manual.46e49bd74b1d":"Создание сцены","manual.f779d891c1f2":"Сцена — это стопка источников, компонуемых на видеокарте. Один источник может использоваться в нескольких сценах.","manual.5a1c5f778fdb":"В доке <strong>Источники</strong> нажмите <strong>Добавить источник</strong> и выберите тип: <strong>Дисплей</strong>, <strong>Окно</strong>, <strong>Игра</strong>, <strong>Веб-камера / карта захвата</strong>, <strong>Браузер</strong>, <strong>Медиа</strong>, <strong>Изображение</strong>, <strong>Текст</strong>, <strong>Цвет</strong> или <strong>Звук</strong>.","manual.2a2d9e2015b5":"Добавьте <strong>Захват дисплея</strong>: предпросмотр программы заполнится вашим экраном.","manual.80c8e9c8176f":"Добавьте источник <strong>Веб-камера</strong>, перетащите его в угол холста и измените размер с помощью маркеров.","manual.264150f36676":"Добавьте поверх наложение <strong>Изображение</strong> или <strong>Браузер</strong>. Порядок в списке — это порядок на холсте: верхний элемент списка находится на переднем плане.","manual.a329c46899d6":"Создайте ещё сцены в доке <strong>Сцены</strong> — например, «Скоро начнём», «Игра» и «Скоро вернусь» — и переключайтесь между ними.","manual.9c8d5730d1bb":"<strong>Совет.</strong> Измените свойства общего источника один раз — и они изменятся во всех сценах, где он используется.","manual.fd869e76d280":"<strong>Предпросмотр.</strong> В Windows, macOS и Linux с X11 предпросмотр программы рисуется прямо с видеокарты, поэтому перетаскивание, масштабирование и поворот происходят мгновенно. В Wayland используется стандартный предпросмотр с тем же редактированием на холсте.","manual.87eca68fecaa":"Фильтры и переходы","manual.36a962cf3902":"Накладывайте фильтры на каждый источник прямо на видеокарте и выбирайте, как одна сцена сменяется другой.","manual.4708b4dbab34":"Добавление хромакея","manual.9df34cebcaf5":"Щёлкните правой кнопкой мыши по источнику — например, по камере с зелёным фоном — и выберите <strong>Фильтры</strong>.","manual.9981601a6174":"Добавьте <strong>Хромакей</strong> и настройте <strong>Ключевой цвет</strong>, <strong>Сходство</strong>, <strong>Плавность</strong> и <strong>Растекание</strong>: ключевой цвет исчезнет с холста прямо на ходу.","manual.b76bd309a9f6":"Добавляйте другие фильтры по мере необходимости — <strong>Цветокоррекция</strong>, <strong>LUT</strong>, <strong>Размытие</strong>, <strong>Маска</strong>, <strong>Резкость</strong> — и перетаскивайте их, чтобы изменить порядок в цепочке.","manual.db41fe5a40e4":"Настройка перехода","manual.bea9e11be98d":"В доке <strong>Управление</strong> откройте выбор перехода, выберите <strong>Срез</strong>, <strong>Растворение</strong>, <strong>Сдвиг</strong>, <strong>Смахивание</strong>, <strong>Стингер</strong> или <strong>Люма-шторка</strong> и задайте длительность.","manual.eada58ce5b2e":"Для <strong>Стингера</strong> выберите медиафайл и точку перехода; для <strong>Люма-шторки</strong> выберите градиент и его мягкость.","manual.79756cb8b209":"Переключите сцену, чтобы увидеть переход. В режиме студии он воспроизводится, когда вы отправляете предпросмотр в программу.","manual.2c0c025b4264":"Компоновщик и визуальные эффекты","manual.b768e85eff32":"3D-наклон, выходные кеи, заморозка и клонирование, семейство размытий, переходы с движением и правилами, студия шейдеров, маски Безье и стингеры с трек-маттом.","manual.d2b720eca5a5":"3D-наклон и перспектива","manual.d665cc2f2296":"Откройте <strong>Изменить трансформацию…</strong> для элемента и задайте <strong>Наклон X</strong>, <strong>Наклон Y</strong> и силу <strong>Перспективы</strong>, чтобы закрепить источник в 3D. Трансформация без наклона отображается точно так же, как раньше.","manual.c4077ba2b72d":"Выходные кеи","manual.d4220af54ed9":"Откройте <strong>Инструменты → Выходные кеи…</strong> и добавьте любой источник как слой поверх <strong>Вывода программы</strong> — над всеми сценами и при любой смене сцены: логотип канала, значок «В эфире», нижнюю плашку.","manual.0677e571c1f8":"Меняйте порядок слоёв и задавайте каждому непрозрачность, положение, размер и включение или выключение. Они одинаково появляются в предпросмотре, записи, трансляции и мультивью.","manual.1e484119e149":"Стоп-кадр и клонирование источников","manual.4cdb8e22f58b":"Щёлкните правой кнопкой мыши по источнику, откройте <strong>Фильтры</strong> и добавьте <strong>Заморозку</strong>: она одновременно удерживает последний кадр в программе, предпросмотре, записи и трансляции. Выключите её, чтобы снять заморозку.","manual.59fd957b48dc":"Нажмите кнопку <strong>Клонировать</strong> (⧉) в строке источника, чтобы разместить один сигнал в нескольких сценах или местах; у каждого клона своя трансформация и свои фильтры.","manual.a90410d6b30c":"Размытия","manual.eeb69e428aa3":"В <strong>Фильтрах</strong> источника добавьте одно из размытий помимо гауссова: <strong>направленное</strong> (след движения под углом), <strong>радиальное</strong> (вращение вокруг центра), <strong>Зум</strong> (след наезда камеры) или <strong>Пикселизация</strong> (мозаика).","manual.54261c9f6b8f":"Переход «Перемещение» и правила переходов","manual.ef17a04962be":"Выберите переход <strong>Перемещение</strong>: элементы, присутствующие в обеих сценах, плавно переходят из старого положения, масштаба, поворота и обрезки в новые вместо резкой смены, а элементы, которые есть только в одной сцене, плавно появляются или исчезают.","manual.e31792f9e737":"Откройте <strong>Инструменты → Правила переходов…</strong>, чтобы задать для пары сцен собственный переход и длительность. Для собственного появления элемента задайте плавное <strong>Проявление</strong> в <strong>Изменить трансформацию…</strong>.","manual.bb4e30a1ea68":"Студия шейдеров WGSL","manual.e475acf03bea":"Добавьте <strong>пользовательский эффект WGSL</strong> как фильтр и редактируйте его вживую. Его ползунки создаются из аннотаций <code>// @param</code>, а во встроенной галерее есть оттенки серого, инверсия, строки развёртки и виньетка.","manual.424ca3316822":"<strong>Совет.</strong> Шейдер компилируется и проверяется по мере набора. Некорректный шейдер игнорируется, и источник отображается без фильтра — сбоя не будет никогда.","manual.c24e8b5ee2c0":"Маски Безье","manual.37870edaacbc":"Добавьте фильтр <strong>Маска Безье</strong> и нарисуйте замкнутый контур: перетаскивайте маркеры, дважды щёлкните, чтобы добавить точку, щёлкните правой кнопкой мыши, чтобы удалить её. Есть готовые фигуры, растушёвка для каждого края и инверсия.","manual.f44ad1306530":"Экспортируйте любой контур как узор <strong>люма-шторки</strong> в оттенках серого, чтобы использовать фигуру повторно в качестве перехода.","manual.e4c8b0c52b3e":"Стингеры с трек-маттом","manual.b35494db6ce6":"Настройте стингер так, чтобы он передавал прозрачность как <strong>Трек-матт</strong>, с заливкой и маской <strong>Рядом</strong> или <strong>Друг над другом</strong>, — тогда прозрачность переживёт кодеки, которые её отбрасывают (H.264 и HEVC). При желании <strong>приглушайте звук программы</strong> под собственным звуком стингера, пока он играет.","manual.3879f0c73d18":"Наложения и другие источники","manual.cea21c089e39":"Повтор, плейлисты, титры, индикаторы, наложение статистики, таймеры, наложение ввода и два сетевых сигнала — всё это в меню <strong>+ / Добавить источник</strong> дока <strong>Источники</strong>.","manual.4a459b922e4b":"Мгновенный повтор","manual.2e042aa67065":"Сначала включите буфер повторов (<strong>Включить повтор</strong> в доке <strong>Управление</strong>), затем выберите <strong>Мгновенный повтор</strong> в <strong>+ / Добавить источник</strong> и разместите его в сцене.","manual.d7645da473a6":"Выведите последние секунды в программу горячей клавишей повтора — они копируются без перекодирования и воспроизводятся со скоростью <strong>100%</strong>, <strong>50%</strong> или <strong>25%</strong>, то есть замедляются, а не дополняются придуманными кадрами. Во время воспроизведения можно перематывать или ставить на паузу.","manual.5b8095e70de0":"В конце источник очищается сам, так что эфир сам возвращается к живой картинке.","manual.6433eaab9b10":"<strong>Совет.</strong> Замедленный повтор намеренно идёт без звука: замедленный звук был бы размазанным, поэтому его не подделывают, а просто не воспроизводят.","manual.f0b63d46cd74":"Медиаплейлист и фоновая музыка","manual.37ed12f9d130":"Добавьте <strong>Медиаплейлист (без пауз)</strong> и составьте упорядоченный список с точками входа и выхода и точками сигнала для каждого элемента. Весь список воспроизводится через один декодер, поэтому стыки точны до кадра и действительно без пауз.","manual.ef41fa6ad9b5":"Выберите режим воспроизведения — <strong>Повтор</strong>, <strong>Перемешать</strong> или <strong>Удерживать последний</strong> — и переходите по списку горячими клавишами «следующий» и «предыдущий». Плейлист только со звуком показывает на холсте <strong>название текущего трека</strong> и воспроизводится через собственный канал микшера; нажмите кнопку <strong>Мониторинг</strong> этого канала, чтобы его услышать.","manual.6e641ae2bd92":"Для музыки, которая звучит без изображения на экране, выберите вместо этого <strong>+ / Добавить источник → Фоновая музыка…</strong> и укажите один или несколько файлов <code>.mp3</code>, <code>.wav</code> или <code>.flac</code>, при желании в случайном порядке. Она заглушает собственный звук видеофона, поэтому всегда слышно только что-то одно.","manual.b9aad55133bf":"Конструктор титров и табло","manual.5382c093aaef":"Добавьте <strong>Титр / табло</strong>, чтобы открыть конструктор: накладывайте слои <strong>Текст</strong>, <strong>Изображение</strong> и <strong>Форма</strong>, с текстом с обводкой и тенью и анимациями появления и исчезновения (затухание, сдвиг, шторка).","manual.7b8fea70655a":"Привяжите поля к отслеживаемому файлу (ячейке CSV или указателю JSON) или к переменной студии, а затем управляйте ими вживую: меняйте имя, правьте счёт или запускайте анимацию, не трогая сцену.","manual.88a9422e37a9":"Аудиовизуализатор","manual.87f4a5bdd624":"Добавьте <strong>Аудиовизуализатор</strong> и выберите стиль — <strong>Спектральные полосы</strong>, <strong>Осциллограф</strong> или стерео <strong>VU-индикаторы</strong>, — затем привяжите его к любому каналу микшера, дорожке или мастер-миксу. Он показывает и звук фонового видео.","manual.0ae90a461adb":"В <strong>Свойствах</strong> источника включите <strong>Классические цвета</strong> для зелёной, жёлтой и красной зон или оставьте их выключенными для одного сплошного цвета. Там же размер, число полос и скорость спада.","manual.0d1ceffb08ba":"<strong>Совет.</strong> Визуализатор слушает сигнал <strong>после фейдера</strong>, поэтому заглушённый источник выглядит ровной линией: он показывает ровно то, что вы слышите.","manual.ec642e1cf0cc":"Наложение статистики, таймер сплитов и наложение ввода","manual.6b4fe6f81cb0":"Добавьте <strong>Статистика производительности (HUD)</strong>, чтобы показать на холсте измеренные значения из дока статистики — кадры в секунду, CPU, память, время компоновки на GPU, пропущенные кадры и текущий битрейт; каждую строку можно включить или выключить. Загрузка GPU намеренно не показывается, потому что она не измеряется.","manual.cbd8a4b88736":"Добавьте <strong>Спидран-таймер сплитов</strong>, импортируйте файл LiveSplit <code>.lss</code> и ведите забег с глобальными горячими клавишами сплита, отмены, пропуска и сброса, сравнивая результат с личным рекордом, лучшими сегментами или средним. Файл только читается; забег никогда не записывается обратно.","manual.fbf4bbeaf903":"Добавьте <strong>Наложение ввода (клавиши/геймпад)</strong>, чтобы вживую показывать клавиатуру, мышь и геймпад в одном из четырёх макетов (WASD, компактная клавиатура, геймпад с двумя стиками, 8-позиционный файтстик). Клавиатура и мышь работают в Windows; геймпады — во всех трёх системах.","manual.bf794edb3c25":"Панель соцсетей и каналов","manual.5f898056ef11":"Добавьте <strong>Панель соцсетей</strong> через <strong>+ / Добавить источник</strong>: панель со списком ваших имён пользователя. Выберите платформу для каждой строки — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> в виде цветных значков или <strong>Свой</strong> с собственной подписью и цветом — и введите имя пользователя (например, <code>@mychannel</code>). Добавьте необязательную строку заголовка («Подписывайтесь»), измените порядок строк и задайте размер текста и цвета.","manual.1dab9389547a":"Каждое поле остаётся доступным для правки в <strong>Свойствах</strong> источника. Строки без имени пользователя пропускаются, так что можно держать полный список и заполнять только то, чем вы пользуетесь.","manual.1a4ac3c2e0bf":"Избранное сообщение чата","manual.c5d58a7d58be":"Откройте <strong>Инструменты → Избранное сообщение чата…</strong> (или палитру команд). В окне перечислены самые новые строки из всех работающих наложений чата: нажмите <strong>Закрепить</strong> у одной из них, чтобы закрепить её в программе в виде баннера, который видят зрители трансляции и записи.","manual.162d364796a2":"Задайте в диалоге цвета <strong>баннера</strong> и <strong>текста</strong> и нажмите <strong>Убрать</strong>, чтобы снять его с эфира. Само закрепление намеренно сбрасывается при перезапуске: вчерашний привет никогда не всплывёт в сегодняшнем эфире.","manual.89a84c53e014":"Подсветка курсора и эффекты щелчков","manual.d0a5d9fb047d":"Щёлкните правой кнопкой мыши по захвату дисплея или окна, откройте <strong>Фильтры</strong> и добавьте <strong>Эффекты курсора</strong>: <strong>Ореол курсора</strong> (цвет и радиус), различающиеся по цвету <strong>Волны от кликов</strong> левой и правой кнопкой и необязательный <strong>Показ клавиш</strong> рядом с указателем. Изменения видны сразу.","manual.4a17c44757e4":"<strong>Примечание.</strong> Эффекты курсора работают только в Windows; macOS и Linux рисуют курсор сами. Наложение ввода и показ клавиш считывают ввод <strong>только пока они включены</strong> и рисуют его прямо в изображении: ничего не сохраняется и не журналируется.","manual.8bdb1aadf964":"Сетевые источники: приём по LAN и Freally Link","manual.797fe86a1fe8":"Добавьте <strong>Приём по LAN (приёмник SRT/RTMP)</strong>, чтобы открыть приёмник на этом компьютере, затем направьте на показанный адрес (есть и QR-код) приложение камеры на телефоне, кодировщик или второй компьютер. Сигнал появится в сцене с собственным каналом микшера. SRT может использовать необязательную парольную фразу AES; у RTMP нет собственной аутентификации, поэтому форма предпочитает SRT.","manual.e2761818ccef":"Чтобы обмениваться сигналом между двумя копиями Freally Capture, включите вывод <strong>Freally Link</strong> на <strong>отправляющем</strong> компьютере и задайте его <strong>Ключ сопряжения</strong> — без ключа вывод не включится. На <strong>принимающем</strong> компьютере добавьте <strong>Freally Link (другой экземпляр)</strong>, нажмите <strong>Сканировать LAN</strong> и введите ключ: программа отправителя появится как источник. Ни одной из сторон не нужен ffmpeg, а получатель без ключа не увидит ни одного кадра.","manual.a793cb271e32":"<strong>Примечание.</strong> Оба сетевых источника <strong>выключены, пока вы их не добавите</strong>, остаются в пределах вашей собственной сети и никогда не обращаются к интернету: никто вас не находит, и ничто не подключается наружу.","manual.de10be5dcf2c":"Обратный отсчёт «Скоро начнём»","manual.71b47ef78ea4":"Экран ожидания перед эфиром в один щелчок: крупный обратный отсчёт до начала поверх изображения, GIF, видео, градиента или музыки, который мигает на нуле и ждёт, пока вы переключитесь на эфир.","manual.303493002776":"Добавление обратного отсчёта","manual.f78f2994b5d5":"В доке <strong>Источники</strong> откройте <strong>+ / Добавить источник</strong> и выберите <strong>Скоро начнём…</strong>. В сцену будет помещён обратный отсчёт на весь холст — подпись над крупным числом.","manual.c4bff5a4f06e":"Введите <strong>подпись</strong> («Скоро начнём», «Скоро вернусь»), затем задайте время в <strong>выборе времени</strong>: <strong>час</strong> (1–12), <strong>минуту</strong> с шагом в пять минут и <strong>AM</strong> или <strong>PM</strong>. Источник отсчитывает время до этого момента суток.","manual.59b00df516f1":"На нуле обратный отсчёт <strong>мигает и останавливается на 0:00:00</strong> — он никогда не переключает сцены сам. Переключитесь на живую сцену, когда будете готовы. Каждое поле остаётся доступным для правки в <strong>Свойствах</strong> источника.","manual.1dfb2d817d39":"Выбор фона","manual.edc2450aeecd":"Выберите заливку: двухцветный <strong>Градиент</strong> (по умолчанию), <strong>Сплошной</strong> цвет, <strong>Изображение</strong> (нажмите <strong>Обзор…</strong>) или <strong>Прозрачный</strong>, чтобы сквозь него был виден источник ниже.","manual.07a5fd9ac032":"Выберите файл <strong>GIF</strong> или <strong>видео</strong>, и он будет крутиться по кругу за цифрами, <strong>вписанный по размеру и по центру</strong>, так что видна вся картинка и ничего не обрезается.","manual.1cda5be75376":"Добавьте <strong>Фоновую музыку</strong> кнопкой <strong>Обзор…</strong> в диалоге (MP3, WAV, FLAC, M4A, AAC, OGG или Opus). Она повторяется по кругу, слышна в предпросмотре и попадает в запись и трансляцию. Собственный звук видеофона заглушается, поэтому всегда слышно только что-то одно.","manual.b39b6b7add20":"<strong>Совет.</strong> Для музыки на простом фоне оставьте фон «Градиент» или «Прозрачный» и добавьте музыку: получится чистый обратный отсчёт с саундтреком.","manual.84f506f4fca5":"Аудиомикшер","manual.480e299c8728":"Микшируйте все звуковые источники, отправляйте их максимум на 6 дорожек и очищайте звук микрофона — всё вживую.","manual.bcbc220b3e63":"Каждый звуковой источник — это канал в <strong>Микшере</strong>: его имя, индикатор уровня, фейдер, заглушение, мониторинг, фильтры и точки дорожек (1–6).","manual.03b920dc5376":"Перетащите фейдер, чтобы задать уровень, нажмите <strong>Заглушить</strong> или <strong>Мониторинг</strong> и отправьте источник на любую из 6 дорожек.","manual.9a9991c7dc36":"Откройте <strong>фильтры</strong> источника и добавьте <strong>Шумоподавление</strong> (классическая обработка сигналов, без ИИ), <strong>Шумовые ворота</strong>, <strong>Компрессор</strong>, <strong>Лимитер</strong>, <strong>Эквалайзер</strong> или <strong>Усиление</strong>.","manual.1a58b91bc5aa":"Назначьте горячую клавишу <strong>push-to-talk</strong> или <strong>push-to-mute</strong> и следите за громкостью программы по индикатору <strong>LUFS</strong>.","manual.7158a36ed4d5":"<strong>Примечание для macOS.</strong> macOS сама по себе не даёт приложениям доступ к тому, «что вы слышите». Используйте звук ScreenCaptureKit (macOS 13 или новее), если он доступен, или установите виртуальное устройство, например BlackHole, и выберите его как источник системного звука. Freally Capture подскажет вам, что делать, и продолжит запись, даже если один из источников не удаётся открыть.","manual.bfdd510698ef":"Запись","manual.e39b756fce99":"Записывайте программу на несколько дорожек аппаратным кодировщиком видеокарты или без потерь в собственном формате Capture.","manual.ad438c2dbf4b":"В <strong>Настройки → Вывод</strong> выберите кодировщик. Freally Capture находит <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> или <strong>VideoToolbox</strong> и выбирает лучший; <strong>x264</strong> на процессоре всегда доступен как запасной вариант.","manual.3bc1870f8449":"Выберите контейнер — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> или <strong>WebM</strong> — или собственный формат Capture без потерь <strong>freally-video</strong> (<code>.frec</code>), которому не нужно ничего дополнительно устанавливать.","manual.e2a332927058":"Отправляйте источники на звуковые дорожки (до 6), чтобы микрофон, системный звук и ваши гости оставались раздельными для монтажа. При желании включите <strong>разбиение файлов</strong> и <strong>локальную копию с отдельными дорожками во время трансляции</strong>.","manual.e0fa2f5a9430":"Нажмите <strong>Начать запись</strong> в доке <strong>Управление</strong>. Зелёная точка <strong>REC</strong> показывает время и число дорожек. Нажмите <strong>Остановить</strong>, чтобы завершить файл.","manual.b1eb969490f1":"<strong>Примечание о кодеках.</strong> MP4 с H.264 и AAC (а также HEVC или AV1) использует запатентованные кодеки, которые предоставляет <strong>ffmpeg</strong>, а он <em>не входит в сборку</em>: Freally Capture загружает его, когда он впервые понадобится, и проверяет. Формату без потерь <strong>freally-video</strong> ничего загружать не нужно.","manual.691bff5377a8":"Запись и повторы в глубину","manual.3c2d08430816":"Всё, что окружает файл: отдельные записи каждого источника, обрезка клипов, настоящая прозрачность, разбиение и метки по событиям, задачи после записи, проверка целостности и тайм-код SMPTE. Всё это выключено, пока вы это не включите, и ничто из этого не выходит в интернет.","manual.537ffa2b9063":"ISO-запись каждого источника","manual.e57aa725fa41":"Откройте <strong>Настройки → Вывод</strong> и найдите <strong>ISO-запись</strong>. Включите <strong>Записывать „{name}“ как отдельный ISO-файл</strong> для каждого источника, который нужен в чистом виде: каждый записывается до компоновки, в размере холста и с его частотой кадров, так что каждый файл ложится на монтажную шкалу точно вровень с программой. Каждый удалённый гость — это источник, поэтому и каждый гость получает свой файл.","manual.4bce8f25ec9c":"Оставьте отмеченным <strong>Записывать с фильтрами источника</strong>, чтобы получить обработанную картинку, или снимите флажок, чтобы записать источник как есть, и выберите для каждой записи <strong>Формат ISO</strong> и <strong>Видеокодировщик ISO</strong>. Звук снимается после фильтров, но до фейдера и заглушения, так что решение при микшировании никогда не заглушит ISO-файл.","manual.7f29ae4e2c55":"<strong>Совет.</strong> Две ISO-записи спокойно тянет видеокарта среднего уровня; каждая следующая стоит ещё одного рендеринга и кодирования, и панель об этом сообщает.","manual.b2aad668b8b9":"Обрезка повторов и клипов","manual.c8af16e1cd4f":"Откройте сохранённую запись в окне <strong>Обрезать</strong> из списка записей, переходите по ней кнопками <strong>Кадр назад</strong> и <strong>Кадр вперёд</strong> и задавайте точки кнопками <strong>Точка входа</strong> и <strong>Точка выхода</strong> прямо во время просмотра.","manual.1f80dfd03a36":"Перед экспортом проверьте значок. Зелёный <em>«Экспорт без перекодирования»</em> означает, что точка входа стоит на ключевом кадре (почти мгновенно и без потерь); янтарный значок предупреждает, что будет перекодирование, — нажмите <strong>Ключевой кадр</strong>, чтобы привязать точку входа и получить обрезку без потерь. Нажмите <strong>Экспортировать клип</strong> или <strong>9:16</strong>, чтобы экспортировать вертикальную версию.","manual.8a92b0b480f4":"Запись с прозрачностью","manual.79bfd450e6aa":"В <strong>Настройки → Вывод</strong> включите <strong>Записывать с прозрачностью (альфа)</strong>, чтобы записывать программу на прозрачном фоне в формат Capture <code>.frec</code>. Запись получает собственный прозрачный рендеринг, поэтому в предпросмотре и трансляции остаётся обычная картинка. Из списка записей экспортируйте <code>.mov</code> в <strong>ProRes 4444</strong> или <strong>QuickTime Animation (QTRLE)</strong> для вашего монтажного редактора; MP4 и MKV сводят прозрачность.","manual.fade0a9d0454":"<strong>Примечание.</strong> Прозрачность — это всего лишь флаг в заголовке <code>.frec</code>, поэтому такие файлы воспроизводятся везде, где воспроизводится <code>.frec</code>, а старые файлы открываются как непрозрачные.","manual.33e5c9a96c5d":"Разбиение и автоматические метки","manual.5596d47693a3":"В настройках разбиения для <code>.frec</code> выберите, когда начинать новый файл: при <strong>смене сцены</strong>, <strong>маркере</strong> или <strong>шаге сценария</strong>. Каждая часть начинается точно с кадра этого события и длится не меньше секунды, так что всплеск событий не создаст кучу крошечных файлов.","manual.7fc20a49c196":"Включите <strong>Автоматически ставить метки глав по событиям студии</strong>, чтобы отмечать главами смены сцен, сохранённые повторы, переподключения, всплески пропущенных кадров, тревоги и действия правил. Они попадают в названия глав MKV и в файл <code>.chapters.txt</code> рядом с записью — вместе с метками, которые вы ставите горячей клавишей.","manual.519fceb746f3":"После записи: конвейер и проверка целостности","manual.561bb55d7a18":"Соберите <strong>Конвейер после записи</strong> для каждого профиля из фиксированного набора шагов — <strong>Проверить</strong>, <strong>Ремукс в MP4</strong>, <strong>Нормализовать громкость</strong>, <strong>Переименовать</strong>, <strong>Переместить в папку</strong>, <strong>Скопировать в папку</strong>, <strong>Показать в файловом менеджере</strong> и <strong>Уведомить скрипты Lua</strong>. Он работает в фоне с живой очередью и останавливается при первой же ошибке. Шага «выполнить любую команду» намеренно нет.","manual.2f93cddd1f21":"Запускайте проверку целостности после записи или когда захотите, чтобы получить простой ответ — OK, предупреждение или ошибка — по пунктам <strong>Контейнер</strong>, <strong>Непрерывность видео</strong>, <strong>Непрерывность аудио</strong>, <strong>Чередование аудио и видео</strong> и <strong>Длительность</strong>. Файлы <code>.frec</code> проходят глубокую проверку; остальные файлы — проверку структуры и декодирования через ffmpeg.","manual.0d291aee5546":"Экспорт копии для обмена при остановке","manual.124d2a00ed27":"В <strong>Настройки → Вывод</strong>, когда в качестве контейнера выбран <code>.frec</code>, отметьте <strong>Также сохранять общедоступный MP4 рядом с мастером</strong>. Когда запись завершится, фоновый экспорт создаст рядом с мастером без потерь файл <code>.mp4</code>, который сможет воспроизвести кто угодно.","manual.a37303723389":"Копия появляется в очереди после записи, получает имя, которое никогда ничего не перезапишет, и никогда не затрагивает мастер. Функция выключена, пока вы её не включите.","manual.7ed8656eb1ff":"Тайм-код SMPTE LTC","manual.3d97874c3064":"Откройте <strong>Тайм-код SMPTE (LTC)</strong>, включите <strong>Генерировать LTC на дорожку</strong> и выберите дорожку микшера и частоту кадров, чтобы подавать тайм-код на внешние рекордеры и камеры. Задайте в <strong>Читать LTC из</strong> звуковой вход, чтобы показывать строку тайм-кода в наложении статистики и ставить метки глав по LTC. Классический звуковой тайм-код, полностью офлайн, с точностью до одного кадра при 24, 25 и 30 fps.","manual.a9f690169703":"Выход в эфир","manual.8f6df4580812":"Транслируйте прямо со своего компьютера на платформу по RTMP или RTMPS — никогда через какой-либо наш сервер.","manual.dba22b61cdcc":"Откройте <strong>Настройки → Трансляция</strong> и нажмите <strong>Добавить направление</strong>. Выберите <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> или <strong>Свой RTMP</strong>.","manual.2192731aac47":"Вставьте свой <strong>ключ трансляции</strong> — он хранится на вашем компьютере и отображается скрытым — и задайте битрейт и кодировщик для этого сервиса.","manual.040014e94f16":"Нажмите <strong>В эфир</strong> в доке <strong>Управление</strong>. Загорится индикатор <strong>В эфире</strong>, а док статистики покажет битрейт, пропущенные кадры и состояние трансляции.","manual.0cd441959cb4":"Если соединение прервётся, Freally Capture <strong>переподключится сам</strong>, а локальная запись продолжится, что бы ни происходило с трансляцией. При желании задайте <strong>задержку трансляции</strong>.","manual.dc8ebcea4893":"Чтобы остановить трансляцию, нажмите <strong>Завершить трансляцию</strong>.","manual.973adc03e43c":"Безопасность эфира","manual.53fa9293a65e":"Как не потерять эфир — до, во время и после.","manual.de8792b14216":"До: предполётная проверка перед выходом в эфир","manual.ed9a4b7bfaf5":"Нажатие <strong>В эфир</strong> сначала запускает контрольный список: у направлений трансляции есть ключи, найден рабочий кодировщик, все источники в порядке и для записи хватает места на диске — каждый пункт зелёный или красный, с исправлением в один щелчок, — а также напоминания об уровнях микрофона и звука рабочего стола и о буфере повторов, которые никогда не блокируют эфир только с экраном. Отдельная настройка может <strong>не давать выйти в эфир, пока все блокирующие проверки не станут зелёными</strong>; в остальных случаях доступна кнопка «Всё равно выйти в эфир».","manual.9b63c5c64ba1":"Во время: тревоги, состояние и резервирование","manual.9c386b745073":"<strong>Тревоги безопасности</strong> следят за происходящим, пока вы в эфире или записываете: тишина в звуке программы, продолжительное клиппирование, чёрная или застывшая картинка и <em>прогноз</em> нехватки места на диске («осталось около 22 минут при текущем битрейте»). Они появляются в виде баннера, который можно закрыть, и озвучиваются экранными дикторами — это никогда не диалог, прерывающий эфир.","manual.b7c8c66a5330":"<strong>Панель состояния источников</strong> (палитра команд → «Состояние источников…») показывает для каждого источника состояние, частоту кадров, возраст последнего кадра, пропущенные кадры и перезапуски, с кнопками <strong>Перезапустить</strong> и <strong>Свойства</strong> для каждого.","manual.92bd60ef963b":"Если аппаратный кодировщик откажет посреди трансляции или записи — сброс драйвера, перегруженная видеокарта, — <strong>резервирование кодировщика</strong> переключится на другой аппаратный кодировщик или на x264. Трансляция переподключится и продолжится, запись продолжится в новом файле, а сообщение точно расскажет, что произошло. Сетевые проблемы никогда не вызывают переключения.","manual.50a02fe4fe7b":"<strong>Тревожная кнопка</strong> (глобальная горячая клавиша на ваш выбор) переключает программу — а также вертикальный холст и все проекторы — на заставку конфиденциальности, останавливает весь захват и заглушает весь звук, включая микрофон, при этом трансляция и запись остаются подключёнными. Для возврата нужно осознанное подтверждение в два шага. Цвет или изображение заставки задаются рядом с горячей клавишей в <strong>Настройки → Горячие клавиши</strong>.","manual.a73a2857361e":"После: надёжные записи и упорядоченный выход","manual.bf07b060e7e7":"Записи MP4 и MOV пишутся <strong>фрагментами</strong>, поэтому даже после сбоя или отключения питания остаётся воспроизводимый файл (MKV и <code>.frec</code> и так были устойчивы). Если сессия оборвалась посреди записи, при следующем запуске будет предложено <strong>Восстановить</strong> её в один щелчок в копию <code>(repaired)</code>; оригинал никогда не затрагивается.","manual.da5eeb31c1b8":"При выходе во время эфира, записи или с включённым повтором приложение показывает, что произойдёт, а затем завершает работу <strong>по порядку</strong>: заканчивает трансляцию, завершает запись, сохраняет буфер повторов, сохраняет вашу работу.","manual.26b3f2c32e05":"<strong>Имена файлов записей</strong> строятся по шаблону (<strong>Настройки → Вывод</strong>) из токенов — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — для записей, повторов и стоп-кадров, с отдельными папками для повторов и стоп-кадров.","manual.27c3f23547ac":"<strong>Экспорт диагностики</strong> сохраняет набор технических сведений в файл на вашем компьютере; он собирается по строгому белому списку, так что ключи трансляции, пароли, пути и имена файлов в него никогда не попадают. Вы можете сначала прочитать, что в нём; он остаётся там, куда вы его сохранили, и никуда не отправляется.","manual.5199babf9b90":"Источники и устройства","manual.306121fdda68":"Всё, что находится между объективом и холстом: тестовые сигналы, калибровка синхронизации, текст из файла, таймеры, карта горячих клавиш, микшер в глубину и настоящее управление устройствами.","manual.5eacf1ee941f":"Тестовые сигналы и калибровка синхронизации A/V","manual.920b7abd63cc":"Добавьте источник <strong>Тестовый сигнал</strong> (<strong>Источники → + → Тестовый сигнал</strong>): цветные полосы, калибровочная сетка, движущаяся развёртка, настроечный тон 1 kHz на уровне −20 dBFS или комбинированная <strong>вспышка с сигналом</strong> для синхронизации звука и видео — изображение и звук создаются от одних часов. Проверяйте проектор, кодировщик или направление трансляции без подключённой камеры.","manual.788073298328":"Откройте рабочее окно <strong>калибровки синхронизации A/V</strong> (палитра команд → «Калибровка синхронизации A/V…»). Выберите камеру и микрофон, которые нужно выровнять, направьте камеру на мигающую программу (диалог может открыть для этого полноэкранный проектор) и дайте ему поизмерять около двенадцати секунд. Он находит вспышку и сигнал за несколько циклов и предлагает применить измеренное смещение к микрофону; ручной ползунок остаётся как запасной вариант. Измерение идёт через ваш экран и динамики, поэтому их собственные небольшие задержки входят в результат, — а при неудаче сообщается, <em>почему</em>.","manual.825c83c405fb":"Таймеры, часы и текст из файла","manual.85622b429b51":"Источник <strong>Таймер</strong> показывает часы (в вашем собственном формате и с необязательным фиксированным смещением от UTC), <strong>Обратный отсчёт</strong> (на заданное время или до ближайшего момента суток — на нуле он может мигать или переключать сцену), <strong>Секундомер</strong> или <strong>время с момента выхода в эфир или начала записи</strong>. Запускайте, приостанавливайте и сбрасывайте его в <strong>Свойствах</strong> или назначьте две глобальные горячие клавиши, которые управляют <em>всеми</em> таймерами сразу (<strong>Настройки → Горячие клавиши</strong>).","manual.fcd4f802968f":"Источник <strong>Текст</strong> может <strong>читать из отслеживаемого файла</strong> (<strong>Свойства → Читать из файла</strong>): весь файл <code>.txt</code>, одну ячейку CSV (по имени или номеру столбца) или одно значение JSON (по указателю вроде <code>/teams/0/score</code>). Изменения появляются в течение полсекунды. Табло и нижние плашки без какого-либо сервиса за ними.","manual.1d106549f0ce":"Карта горячих клавиш и микшерный пульт","manual.5d6ad89f147c":"<strong>Карта горячих клавиш</strong> (палитра команд → «Карта горячих клавиш…») перечисляет <em>все</em> привязки — глобальные действия и push-to-talk и push-to-mute каждого источника — с поиском и фильтрами и честно отмечает конфликты: одно и то же сочетание, записанное двумя способами, показывается как общее, а о клавише, которую система отказалась регистрировать (потому что она занята другим приложением), так и сообщается. <strong>Экспорт шпаргалки</strong> сохраняет справочник в формате Markdown в папку «Загрузки».","manual.e32e382b9753":"У каждого канала микшера есть <strong>Панорама</strong> (стереобаланс; центральное положение — это ровно отсутствие панорамирования, а двойной щелчок сбрасывает её), <strong>PFL-соло</strong> (в мониторинге слышны только каналы в режиме соло; микс программы никогда не меняется) и сведение в <strong>моно</strong>. Панорама и моно находятся в меню «⋯» канала; соло — на самом канале.","manual.5dbd70dfc92d":"Устройства в глубину: деинтерлейсинг и управление камерой","manual.f8e60899a881":"В <strong>Свойствах</strong> устройства захвата видео есть <strong>Деинтерлейсинг</strong> для чересстрочных сигналов, например с карт захвата, к которым подключены старые камеры и приставки: отбрасывание, bob, линейный, смешивание или адаптивный к движению, с выбором порядка полей. Он работает одинаково во всех системах; при его изменении устройство перезапускается.","manual.34192e6d30fd":"<strong>Управление камерой</strong> — экспозиция, баланс белого, фокус, зум, усиление и другое — появляется в тех же <strong>Свойствах</strong>, пока камера работает. Windows и Linux используют стандартные элементы управления UVC; macOS показывает то, что сообщает система, а это часто ничего, — и панель так и говорит, вместо того чтобы показывать бесполезные ползунки. Каждая настройка сохраняется в <strong>профиле этой камеры</strong> и применяется снова, когда камера подключается обратно или приложение перезапускается; <strong>Сбросить профиль</strong> возвращает значения по умолчанию.","manual.f77f10d8c967":"Автоматизация и управление","manual.726216fb4de1":"Пусть студия управляет собой сама с помощью правил, макросов и аппаратных контроллеров — и каждый из них ограничен одним фиксированным списком команд студии, так что никакая автоматизация не может указать файл, запустить программу или обратиться к интернету.","manual.193521bd4921":"Правила, макросы и переменные","manual.e8ee7ccab125":"Откройте <strong>Инструменты → Правила автоматизации и макросы…</strong> и добавьте правило. Выберите один из девяти триггеров (смена сцены, начало или остановка трансляции, начало или остановка записи, ошибка источника, пересечение порога уровнем звука, переход системы в бездействие, получение фокуса окном, время суток или изменение отслеживаемого файла), добавьте условия (значение переменной, эфир, запись) и выберите действие студии. Каждое правило создаётся <strong>выключенным</strong>: включите его, чтобы оно начало работать.","manual.5deaa7ba718f":"Соберите макрос как именованный список шагов — выполнить действие, подождать, задать переменную — с числом повторов и необязательной глобальной горячей клавишей. Запускайте его из приложения, горячей клавишей, правилом или через API удалённого управления.","manual.30ee5b1326f2":"Задайте в макросе <strong>переменную</strong> студии и используйте её как <code>{{name}}</code> в любом источнике «Текст»: текст изменится в тот же миг, когда макрос задаст значение.","manual.5eb10fc04538":"Контроллеры: MIDI, OSC и сенсорная панель","manual.ba0c838f1688":"Откройте <strong>Инструменты → MIDI-управление…</strong> и обучите его пэду, ручке или фейдеру для действия, макроса, смены сцены, фейдера микшера или заглушения — с подсветкой и моторизованными фейдерами, которые следуют реальному состоянию студии. Ни один MIDI-порт не открывается, пока вы его не выберете.","manual.cc993cb0d974":"Включите <strong>Принимать OSC</strong>, чтобы контроллеры в стиле TouchOSC и световые пульты могли отправлять адреса вроде <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> и <code>/mixer/vol</code>. По умолчанию это выключено, и приём идёт только на этом компьютере, если вы не разрешите свою сеть. У OSC нет собственного пароля.","manual.134e5f4269f9":"Откройте <strong>Инструменты → LAN-панель и tally…</strong>, чтобы отдавать страницу управления — кнопки сцен с живым tally, фейдеры микшера и клавиши действий — любому телефону по QR-коду. Каждый запрос требует пароля, и приём идёт только на этом компьютере, если вы не разрешите свою сеть. Страница tally показывает красный или зелёный на весь экран; добавьте <code>?scene=NAME</code>, чтобы следить за одной сценой.","manual.fc4cd96b860d":"Аккорды и слои горячих клавиш","manual.ec4a9a334753":"В поле горячей клавиши назначьте простое сочетание (Ctrl+Shift+M) или двухшаговый аккорд (Ctrl+K, затем 3) — вторая клавиша перехватывается только пока аккорд ожидает продолжения. Назначьте привязке <strong>Слой</strong>, чтобы она работала только при активном слое; слои остаются переключёнными, пока вы их не смените.","manual.70ad05980925":"Камеры и сценарий эфира","manual.24b33b058b99":"Откройте <strong>Инструменты → PTZ-камеры…</strong>, добавьте камеру по её адресу VISCA-over-IP, сохраните именованные пресеты панорамирования, наклона и зума и свяжите пресет со сценой, чтобы при переходе на эту сцену вызывался нужный план. PTZ остаётся в вашей сети, а камера появляется только потому, что вы ввели её адрес: ничего не ищется.","manual.c9d86b995c5a":"Откройте <strong>Инструменты → Показать сценарий эфира…</strong> и перечислите шаги — сцена, сколько она держится, и необязательные действия — с ручным или автоматическим переходом, живым показом «далее» и оставшимся временем. Сценарий переключает сцены обычным способом, который можно отменить, и никогда не редактирует вашу коллекцию сцен.","manual.5c94bed2d737":"<strong>Примечание.</strong> Каждое правило, макрос, привязка MIDI или OSC, кнопка панели и шаг сценария проходят через тот же фиксированный список команд, что и API удалённого управления, поэтому ни один контроллер не может сделать то, чего не могут собственные кнопки приложения. Каждый сетевой приёмник по умолчанию выключен и остаётся в пределах этого компьютера, если вы не разрешите свою сеть, а настройки OSC и панели предупреждают, что сетевой трафик не шифруется, ещё до открытия порта.","manual.1f3fd1c7ddc9":"Мультистрим","manual.dcac0a03a29b":"Транслируйте на несколько платформ одновременно — прямо со своего компьютера, без промежуточного сервиса ретрансляции.","manual.42d9628818da":"Добавьте два или больше направлений трансляции в <strong>Настройки → Трансляция</strong> и включите каждое из них.","manual.4144fe0d9694":"Задайте для платформы собственные настройки кодировщика, если ей нужен другой битрейт.","manual.cb21d6bb96be":"Нажмите <strong>В эфир</strong>: трансляция идёт сразу на все включённые направления. Док статистики показывает состояние и битрейт каждого направления, а сбой одного направления никогда не обрушивает остальные.","manual.aba9a5f55973":"При желании одновременно записывайте локальную копию с отдельными дорожками и сохраняйте повторы горячей клавишей повтора прямо во время трансляции.","manual.af9343c245a7":"<strong>Сейчас бесплатно.</strong> Все функции — мультистрим, SRT и WHIP, все фильтры, скрипты, повторы, наборы переходов и API удалённого управления — сейчас бесплатны для всех. Будущие версии могут продаваться.","manual.c08320c45003":"Надёжность и понимание трансляций","manual.532ab322d03c":"Репетируйте, измеряйте и разбирайте свой эфир. Всё здесь по умолчанию выключено или нейтрально, и ничто из этого не выходит в интернет.","manual.80390ae1a9d7":"Симулятор сети","manual.7e620ced841e":"В <strong>Настройки → Трансляция</strong> откройте <strong>Симулятор сети (репетиции)</strong> и выберите <strong>Профиль</strong> — <strong>Отельный Wi-Fi</strong>, <strong>Мобильная точка доступа</strong> или <strong>Свой</strong> с собственными значениями <strong>Пропускная способность</strong>, <strong>Задержка</strong>, <strong>Джиттер</strong> и запланированными периодами <strong>Обрыв</strong>. Он влияет только на локальный вывод репетиции, так что вы можете отработать переподключения, мультистрим и выбор битрейта; замедлить настоящий эфир он не может никогда.","manual.b22d8c51e0bd":"Режим репетиции","manual.083772633b86":"Нажмите фиолетовую кнопку <strong>Репетиция</strong>, чтобы прогнать весь конвейер — компоновщик, кодировщик, мультиплексор и настоящую логику переподключения — в локальную заглушку, при этом <strong>ничто не покидает компьютер</strong>. Значок <strong>РЕПЕТИЦИЯ</strong> отмечает каждый элемент управления эфиром, а ваши ключи трансляции даже не считываются, так что репетировать можно ещё до того, как они у вас появятся. Репетицию также можно записать.","manual.184d64047c4c":"<strong>Совет.</strong> Совместите репетицию с симулятором сети, чтобы заранее, задолго до эфира, отработать переподключение при слабом и нестабильном соединении.","manual.d2381a584d24":"Хронология пропущенных кадров","manual.a6a72c5410a8":"<strong>Таймлайн сессии</strong> записывает всю сессию — время рендеринга, очередь кодировщика, битрейт и пропущенные кадры каждого направления, переподключения, смены сцен, метки и тревоги — на одном масштабируемом графике. Если док статистики показывает то, что происходит <em>сейчас</em>, то таймлайн потом отвечает на вопрос «что случилось на 43-й минуте?».","manual.6e9fee1e85fa":"Отчёт о сессии и тест кодировщиков","manual.9dd812cbf648":"Включите <strong>Сохранять отчёт о сессии (HTML + Markdown) рядом с записью</strong> в <strong>Настройки → Трансляция</strong>, чтобы по окончании сессии получить локальную сводку: время работы, средний и пиковый битрейт для каждого направления, время простоя, переподключения, метки, тревоги и расположение записи. Отчёт остаётся на вашем компьютере, а функция по умолчанию выключена.","manual.a9e574b7bd8d":"Используйте <strong>Запустить бенчмарк кодеров…</strong>, чтобы измерить короткие кодирования всеми кодировщиками, пресетами и разрешениями, которые есть на вашем компьютере, — около минуты, полностью офлайн, — а затем нажмите <strong>Применить к настройкам записи</strong> по результату. Неудачи перечисляются, а не скрываются, и тест отказывается запускаться, пока вы в эфире или записываете.","manual.fae310275ed2":"Источники только в трансляции или только в записи","manual.191da176dd0d":"В строке источника используйте <strong>Показать в стриме</strong> / <strong>Скрыть в стриме</strong> и <strong>Показать в записи</strong> / <strong>Скрыть в записи</strong>, чтобы оповещения и чат оставались в прямой трансляции, а запись оставалась чистой, — всё на одном холсте. Основная кнопка с глазом по-прежнему управляет всем, а предпросмотр, проекторы и мультивью всегда показывают всю программу.","manual.46bad2cb618f":"Виртуальная камера","manual.69ebe5277092":"Используйте свою программу как веб-камеру в любом приложении для видеозвонков. <strong>В 1.2.1 — только в Windows.</strong>","manual.ba2b6aa952f7":"Нажмите <strong>Запустить виртуальную камеру</strong> в доке <strong>Управление</strong>. Freally Capture добавит системную камеру с именем <strong>«Freally Capture Virtual Camera»</strong>.","manual.cb3cb4585f19":"В Zoom, Meet, Discord или Teams выберите эту камеру в настройках видео: ваша программа станет веб-камерой.","manual.83db59f4a370":"Нажмите <strong>Остановить виртуальную камеру</strong>, чтобы удалить её.","manual.91c51d55639b":"<strong>По системам:</strong> в <strong>Windows</strong> камера регистрируется для вашего пользователя без прав администратора и удаляется, когда вы её останавливаете. Она <strong>пока не имеет цифровой подписи</strong>, поэтому Windows может о ней предупреждать, а защищённое приложение для видеозвонков может её отклонить; полный тест в настоящем звонке ещё предстоит провести. Камеры для <strong>macOS</strong> и <strong>Linux</strong> — это отдельные компоненты, которых <em>нет в этом выпуске</em>. Freally Capture никогда и ни в одной системе не устанавливает системный компонент, не спросив вас.","manual.98839b8e6880":"Источник-браузер","manual.3ba821584b20":"Вставляйте живую веб-страницу — наложение оповещений, табло, виджет чата — прямо в сцену.","manual.895f07f428cd":"В доке <strong>Источники</strong> нажмите <strong>+</strong> и выберите <strong>Браузер</strong>.","manual.868ee19e975e":"Вставьте адрес <strong>http://</strong> или <strong>https://</strong> и задайте размер и частоту кадров для его отрисовки.","manual.292e94b0a782":"При первом использовании Freally Capture предложит установить компонент <strong>Среда выполнения браузера</strong>. Он загружается, когда вы об этом попросите, и проверяется по хешу — он никогда не входит в сборку приложения, — и его можно снова удалить в <strong>Инструменты → Компоненты</strong>.","manual.cd6d7fbd46ee":"<strong>Загружаются только http и https.</strong> Правило распространяется на каждую смену страницы, а не только на введённый вами адрес: если страница пытается перейти на <code>file://</code>, <code>javascript:</code> или <code>data:</code> — через перенаправление, скрипт, всплывающее окно или фрейм, — переход <strong>отменяется</strong>, так что страница не может прочитать ваши файлы. В Windows страница работает в песочнице Chromium. Среда выполнения <strong>пока не имеет цифровой подписи</strong>. Звук страницы пока не захватывается: эта версия передаёт только изображение.","manual.9c0c8f127dd9":"Захват игр","manual.2c08692420b8":"Захватывайте игру в эксклюзивном полноэкранном режиме, которую обычный захват окна не видит. <strong>Только в Windows.</strong>","manual.9d162e3861e9":"В доке <strong>Источники</strong> нажмите <strong>+</strong> и выберите <strong>Захват игры</strong>. <strong>Сначала прочтите предупреждение</strong>: в нём простыми словами объясняется риск.","manual.4264b41a7732":"Примите риск <em>для этой одной игры</em>, затем выберите запущенную игру из списка.","manual.ab3e826e90f1":"Freally Capture загружает в эту игру небольшой перехватчик и забирает её кадры с собственной частотой кадров игры.","manual.082fd06e18f9":"<strong>Прочтите это перед использованием.</strong> Захват игр работает за счёт <strong>загрузки DLL в игру</strong>. Античиты и антивирусы могут счесть это вмешательством, и учётную запись могут <strong>заблокировать</strong>. Ничего никогда не загружается автоматически: вы соглашаетесь <strong>отдельно для каждой игры</strong>, и это согласие никогда нельзя использовать для другой игры — и оно никогда не передаётся внутри общей коллекции сцен. Если игра отвергает перехватчик, Freally Capture переключается на обычный <strong>Захват окна</strong> с сообщением, а не завершается ошибкой. Игры с HDR и игры на Direct3D 12 тоже используют захват окна. В macOS и Linux этот источник не предлагается.","manual.43fae75af922":"Буфер повторов","manual.40bc664c1c0b":"Держите последние мгновения в памяти, чтобы горячая клавиша сохраняла то, что только что произошло.","manual.7a69241c10c2":"Нажмите <strong>Запустить буфер повторов</strong> в доке <strong>Управление</strong>. Freally Capture хранит последние секунды в буфере фиксированного размера.","manual.684aecea2ba0":"Назначьте глобальную горячую клавишу <strong>Сохранить повтор</strong> в <strong>Настройках</strong>.","manual.66c44777e965":"Нажмите её, чтобы сохранить последние секунды в файл, — не прерывая трансляцию и основную запись. Сообщение «Повтор сохранён» подтвердит это.","manual.4b598d5daf11":"Телесуфлёр","manual.b7fc474ded62":"Плавно прокручивающийся текст для человека в кадре — одновременно на панели в приложении, на полноэкранном проекторе с возможностью зеркального отражения и на сенсорной LAN-панели.","manual.f1c548f77750":"Откройте телесуфлёр в меню <strong>Инструменты</strong>, введите или вставьте текст и задайте скорость и шрифт. Задавайте темп в <strong>символах в секунду</strong> или переключитесь на <strong>BPM</strong> (50–250 ударов в минуту), чтобы читать текст песни в такт музыке; любое из этих изменений сразу меняет темп идущей прокрутки.","manual.3a86eb91938d":"<strong>Метки пауз:</strong> введите <code> -- </code> для короткой паузы или <code> --N </code> для остановки на N секунд, и это превратится в одну метку — курсор перешагивает её, одно нажатие Delete или Backspace удаляет её, а копирование и вставка сохраняют её целиком.","manual.dc7539148aed":"<strong>Запустить обратный отсчёт:</strong> включите необязательный отсчёт 3-2-1, который показывается и в предпросмотре оператора, и на проекторе, чтобы у читающего была секунда перед тем, как текст начнёт двигаться.","manual.f5113c573ac4":"<strong>Откройте проектор</strong> для читающего (зеркальный режим переворачивает изображение для стекла светоделителя). При его открытии окно оператора закрывается, так что вы можете вести трансляцию из главного окна, пока ведущий читает; если включён обратный отсчёт, проектор возвращается к началу, отсчитывает и запускает текст. Воспроизведение, пауза, остановка, перемотка назад и вперёд и перезапуск доступны через экранные элементы управления, горячую клавишу, MIDI, OSC или LAN-панель — все элементы управления остаются синхронными.","manual.5298a60b0152":"<strong>Чтение вслух</strong> озвучивает текст для предварительной проверки собственным синтезатором речи вашей системы: встроенными голосами Windows, macOS, а в Linux — <code>spd-say</code> или <code>espeak-ng</code>, если они установлены. Никакой речевой движок в сборку не входит.","manual.5de1b5efa245":"<strong>Автодополнение</strong> во время набора предлагает слова и фразы светло-серым цветом; нажмите Tab, чтобы принять. У каждого из 18 языков есть собственный словарь на вашем компьютере, который загружается только для языка, на котором вы пишете.","manual.7fb5d22a1670":"Удалённое управление","manual.b2ba73efdcec":"Управляйте студией со Stream Deck или контроллера в стиле Companion — по умолчанию выключено, защищено паролем, на вашем собственном компьютере.","manual.6396674fcd28":"Откройте <strong>Настройки → Удалённое управление</strong>, включите <strong>WebSocket API</strong> (по умолчанию выключен) и задайте <strong>Пароль</strong>.","manual.56e0d6d295bb":"Он принимает подключения на <code>127.0.0.1</code> — только на этом компьютере, — если вы явно не разрешите свою сеть.","manual.344e52e3eba1":"Направьте клиент Companion или Stream Deck на показанный адрес. Переключайте сцены, запускайте переходы, выключайте и включайте звук, начинайте и останавливайте запись и сохраняйте повторы аппаратными кнопками.","manual.6664edd9ad4c":"Удалённые гости и производство эфира","manual.75ce17238f9b":"Превратите сессию с удалёнными гостями в полноценно спродюсированный эфир: до восьми гостей, рисование поверх живой программы, комната ожидания, личные сигналы, связь каждого гостя с первого взгляда и автоматическая сетка. Всё здесь по умолчанию выключено или не назначено, и ничего не подключается, пока вы кого-нибудь не пригласите.","manual.02d9e34002c8":"Сессии с несколькими гостями","manual.5a6c2ec7640d":"Начните сессию с удалёнными гостями и поделитесь ссылкой-приглашением или её QR-кодом: <strong>вы плюс до восьми гостей</strong>, галерея от одного до девяти. Каждый гость — это плитка с собственными кнопками выключения звука, качеством связи, каналом сигналов и выводом в эфир в один щелчок.","manual.34a323a45540":"Гость открывает ссылку в браузере — ничего устанавливать не нужно — и нажимает <strong>Присоединиться</strong>, чтобы передать свою камеру и микрофон. Гость, у которого есть Freally Capture, может вместо этого открыть то же приглашение в приложении. Срок действия приглашения истекает через выбранное вами время.","manual.4e31042e4a6f":"<strong>Примечание.</strong> Изображение и звук идут напрямую между вами и каждым гостем, от узла к узлу, с шифрованием при передаче; через публичный сервис сигнализации проходит только установка соединения. Сессии проверены с четырьмя гостями; возможность большего числа зависит от вашей пропускной способности и процессора.","manual.33ff43cd0616":"Телестратор: рисование поверх живой программы","manual.d29f651d6eb9":"Откройте <strong>Телестратор</strong> и выберите инструмент — <strong>Ручка</strong>, <strong>Маркер</strong>, <strong>Стрелка</strong> или <strong>Эллипс</strong>, — затем рисуйте прямо поверх программы. Ваши пометки становятся частью изображения в момент рисования, поэтому они появляются в записи и трансляции, а не только в вашем предпросмотре.","manual.9aa7fc0273fb":"Выберите <strong>Угасание</strong>, чтобы пометки исчезали через некоторое время, или переключитесь в <strong>Режим доски</strong> и выберите <strong>Оставить</strong>, чтобы они сохранялись до очистки. Рисование учитывает силу нажатия на планшет, а для <strong>Очистить метки</strong> можно назначить горячую клавишу (по умолчанию не назначена).","manual.fc81cd8d37ae":"Комната ожидания","manual.c87beb96ec64":"Включите <strong>Комнату ожидания</strong>, и новые гости будут ждать вне эфира, пока вы проверяете их камеру и микрофон в окне <strong>Просмотр комнаты ожидания</strong>. Когда они будут готовы, нажмите <strong>Вывести в эфир</strong>. Гость видит баннер «вы в комнате ожидания» — в приложении или на веб-странице.","manual.1d47c8224f50":"Сигналы и связь","manual.569d461035c1":"Отправьте гостю личный <strong>Сигнал</strong> — с готовыми вариантами вроде <strong>30 секунд</strong>, <strong>Завершайте</strong>, <strong>Вы следующий</strong> и <strong>Говорите громче</strong> — по уже существующему P2P-каналу сессии. Гость видит его с живым обратным отсчётом, и он никогда не попадает в программу.","manual.c66c9d5359bf":"Панель качества связи","manual.4541cc1ee0f5":"Следите за связью каждого гостя вживую — время приёма-передачи, потеря пакетов, получаемые разрешение и частота кадров, джиттер — с зелёным, янтарным или красным значком и небольшим графиком истории, так что ухудшение связи становится заметно раньше, чем его заметят зрители.","manual.bf8e764221e5":"Автоматические сетки гостей","manual.ffe3c227cdfc":"Включите <strong>Автосетка</strong>, чтобы гости в эфире располагались аккуратной сеткой от одного до девяти, которая сама перестраивается, когда гости подключаются, уходят или выводятся в эфир, — или нажмите кнопку упорядочивания, чтобы сделать это сейчас. Каждое место публикует имя своего гостя как переменную <code>{{guestN}}</code>, так что источник-титр превращается в подпись с именем, которая обновляется сама.","manual.e8630fabd4e5":"Управление студией и рабочий процесс","manual.c8c487196725":"Делайте весь макет переносимым и удобным для обмена, храните именованные версии своих сцен, оформляйте приложение темами и держите любимые действия на расстоянии одного нажатия — всё на вашем компьютере, без сервера.","manual.f87995a7cf6c":"Пакеты сцен и версии","manual.074bb2bf9453":"Откройте диалог рабочего пространства через <strong>Коллекция сцен → Управление коллекциями сцен…</strong>: там собраны инструменты для пакетов, сравнения, снимков, резервных копий и макетов панелей.","manual.8dce3a052a05":"Нажмите <strong>Экспортировать пакет…</strong>, чтобы упаковать текущую коллекцию и её файлы (изображения, медиа, LUT, маски, шрифты) в один переносимый <code>.fcappack</code>. Веб-адреса и сетевые пути перечисляются как <em>внешние</em>, а не упаковываются, а у шрифтов отмечаются их лицензии.","manual.c1bba88df9c5":"Нажмите <strong>Импортировать пакет…</strong> и выберите <code>.fcappack</code>: он появится как новая коллекция, найдёт свои файлы на этом компьютере и переключится на неё.","manual.69e7b9f6e8ab":"Нажмите <strong>Сравнить и объединить…</strong>, чтобы сравнить текущую коллекцию с другой коллекцией, пакетом или снимком. Просмотрите добавленные, удалённые и изменённые сцены, источники, трансформации, фильтры и видимость, затем выберите, какие именно изменения перенести. При выборе сцены переносятся и источники, которые она использует.","manual.862a75c84629":"Нажмите <strong>Снимки…</strong>, назовите контрольную точку и выберите <strong>Сохранить снимок</strong>. <strong>Восстановить</strong> позже вернёт её — текущий макет сначала сохраняется как снимок, так что восстановление никогда не бывает необратимым. Хранится до 50 снимков, с указанием занимаемого ими места на диске.","manual.8058b1480d14":"<strong>Совет.</strong> Снимки — это именованная история в дополнение к автосохранению и отмене. Сделайте снимок перед рискованным изменением, и у вас всегда будет подписанная точка, к которой можно вернуться.","manual.1d55a62a5fdf":"Резервное копирование, восстановление и портативный режим","manual.250b89a976de":"В диалоге рабочего пространства нажмите <strong>Резервная копия и восстановление…</strong>, затем <strong>Экспортировать резервную копию…</strong>, чтобы сохранить всё — настройки, профили и коллекции сцен — в одном файле <code>.fcapbackup</code>.","manual.560e7e269f11":"На новом компьютере нажмите <strong>Восстановить из резервной копии…</strong>, отметьте, что перенести (<strong>Настройки</strong>, <strong>Коллекции сцен</strong>, <strong>Профили</strong>), и выберите <strong>Восстановить выбранное</strong>. Затем перезапустите Freally Capture, чтобы загрузить восстановленные коллекции и профили.","manual.5b26da4b8793":"Чтобы запускать программу с USB-накопителя, положите рядом с ней файл с именем <code>freally-portable.txt</code>: тогда все её данные будут храниться в папке программы, а не в вашем профиле пользователя. <strong>Настройки → О программе</strong> показывает, включён ли портативный режим и где находятся данные.","manual.a31a49d41d7d":"<strong>Примечание.</strong> Ключи трансляции и пароли никогда не записываются в резервную копию — введите их заново после восстановления.","manual.5b446c4ea972":"Темы, макеты и быстрые действия","manual.8eea476bde73":"Откройте <strong>Настройки → Внешний вид</strong> и выберите тему <strong>Пользовательская</strong>, чтобы редактировать палитру с живыми <strong>предупреждениями о контрасте</strong>, затем используйте <strong>Экспорт .fctheme…</strong> или <strong>Импорт .fctheme…</strong>, чтобы поделиться ею.","manual.7cc0bc3a4e74":"В разделе <strong>Макеты панелей</strong> диалога рабочего пространства сохраните текущее расположение под именем и щёлкните по сохранённому макету, чтобы переключиться на него.","manual.c9044c09b979":"В <strong>Настройках</strong> введите запрос в поле <strong>Поиск настроек…</strong>, чтобы перейти к любой настройке; метка показывает, в каких категориях вы что-то изменили с момента открытия.","manual.a4640858ad4d":"Выберите <strong>Инструменты → Быстрые действия…</strong>, чтобы открыть сетку кнопок. Нажмите <strong>Изменить</strong>, затем <strong>Добавить кнопку</strong>, задайте подпись и цвет каждой кнопки и добавьте <strong>страницы</strong>. Кнопка может переключать сцену, запускать макрос, проигрывать пэд звуковой панели или выполнять команду студии.","manual.74ff6472576d":"<strong>Совет.</strong> Кнопки быстрых действий выполняют те же команды студии, что и горячие клавиши, а сетка общая с сенсорной LAN-панелью: настройте её один раз, и она появится и на вашем телефоне.","manual.74a883a037bc":"Настройки","manual.5feaf4600834":"Профили, коллекции сцен, горячие клавиши и язык. Сейчас всё бесплатно, поэтому активировать ничего не нужно. <strong>Настройки</strong> — это одно окно с категориями «Общие», «Внешний вид», «Трансляция», «Вывод», «Повтор», «Горячие клавиши», «Сеть», «Доступность» и «О программе», которое открывается из <strong>строки меню</strong> («Файл», «Правка», «Вид», «Доки», «Профиль», «Коллекция сцен», «Инструменты» и «Справка»).","manual.9f6a04e85e39":"<strong>«Применить» значит применить.</strong> Окно настроек редактирует копию: ничего не меняется, пока вы не нажмёте <strong>Применить</strong> или <strong>ОК</strong>, а <strong>Отмена</strong> возвращает в точности то, что было, включая предпросмотр темы.","manual.3fc0968ef6f9":"<strong>Профили и коллекции сцен:</strong> держите отдельные конфигурации — например, «Трансляция» и «Локальная запись» — и переключайтесь между ними без перезапуска из меню <strong>Профиль</strong> и <strong>Коллекция сцен</strong>.","manual.ce6f52861bdb":"<strong>Горячие клавиши:</strong> назначайте каждое действие из списка, в котором невозможны конфликты: выберите сочетание для одного действия, и оно исчезнет из списков всех остальных действий, так что две функции никогда не делят одну клавишу. <strong>Нет</strong> снова освобождает сочетание.","manual.be52349f05be":"<strong>Доступность:</strong> выберите цвета индикаторов микшера, в том числе набор, безопасный для людей с нарушениями цветового зрения. Всё приложение работает с клавиатуры, а экранные дикторы сообщают о выходе в эфир, записи, переподключении и пропущенных кадрах.","manual.a79c94673558":"<strong>Язык:</strong> выберите один из 18 языков; приложение сразу переключится, а арабский читается справа налево.","manual.59274c49ac87":"Сообщение о проблеме","manual.c02ed8aec89d":"Вы сами решаете, дойдёт ли проблема до разработчика, и видите в точности, что будет отправлено.","manual.4ed327c34aeb":"Когда приложение показывает ошибку, которую вызвало оно само, рядом с ней появляется кнопка <strong>Сообщить</strong>.","manual.95da4b53fdcc":"После сбоя при следующем запуске будет предложено <strong>Сообщить</strong> или <strong>Закрыть</strong>.","manual.6207904599f4":"<strong>Сообщить</strong> открывает в вашем браузере страницу отчёта Freally Capture на этом сайте с уже заполненными техническими сведениями: их можно прочитать, но нельзя изменить. Добавьте, что вы делали, и, если хотите, адрес электронной почты. Ничего не отправляется, пока вы не нажмёте там <strong>Отправить</strong>.","manual.6acd4e789ccd":"Ничего никогда не отправляется в фоновом режиме, а <strong>Закрыть</strong> вообще ничего не отправляет.","manual.69bd78234ffb":"Конфиденциальность и сеть","manual.42f9b04c2640":"У Freally Capture нет учётных записей и телеметрии, и у нас нет облачного сервиса. Вот в точности, что выходит в интернет, а что нет.","manual.81fe73d241a8":"<strong>Никаких учётных записей и телеметрии.</strong> Приложение никогда не просит вас войти в систему и никогда никуда не отправляет ваши сцены, записи или какие-либо данные об использовании.","manual.3735a28566e9":"<strong>Ваша трансляция идёт прямо на платформу.</strong> Она передаётся с вашего компьютера в настроенные вами сервисы — нашего сервера ретрансляции нет.","manual.512b8fa00684":"<strong>Ваши записи остаются на вашем компьютере</strong> в выбранной вами папке. Ничего не загружается в сеть.","manual.c299fcfa1fde":"<strong>Ваши ключи трансляции остаются на вашем компьютере</strong>, отображаются скрытыми и отправляются только в тот сервис, на который вы транслируете.","manual.414a08bd0219":"<strong>Удалённые гости подключаются напрямую, от узла к узлу.</strong> Через публичный сервис сигнализации проходит только установка соединения сессии, и только когда вы начинаете сессию.","manual.20c95c4687b3":"<strong>Наложение чата читает публичный чат</strong> канала, на который вы его направили, так же, как это делает зритель без входа в систему, — без учётной записи, ключа или входа.","manual.efe87d55bed1":"<strong>Два компонента загружаются только тогда, когда впервые понадобятся:</strong> ffmpeg — для кодеков, которых требуют платформы, и среда выполнения браузера — для источника-браузера. Каждый загружается от своего издателя и проверяется перед использованием.","manual.3601a272b3b0":"<strong>Проверка обновлений</strong> загружает один небольшой файл один раз при каждом запуске, а также когда вы выбираете <strong>Проверить обновления…</strong>. Вместе с ней не отправляется ничего ни о вас, ни о вашем компьютере, и ничего не устанавливается, пока вы не согласитесь.","manual.11abc96d8e21":"<strong>Отчёт о проблеме отправляется, только когда вы нажмёте «Отправить»</strong> на странице отчёта, после того как прочитаете, что в нём содержится (см. <a href=\"#report\">Сообщение о проблеме</a>).","manual.804fa6536d40":"<strong>Никакого ИИ.</strong> Каждый фильтр — шумоподавление, хромакей, тональная компрессия — это классическая обработка сигналов. Приложение не содержит ни одной модели машинного обучения и не загружает их."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
